import{_ as e,c as r,o,ae as t}from"./chunks/framework.BbFa6TS3.js";const s="/Cherry-blog/assets/llm.CK1L7Lek.png",l="/Cherry-blog/assets/transformer.BUU0n2ZZ.png",n="/Cherry-blog/assets/moe.5cpnlM2u.png",i="/Cherry-blog/assets/diffusion.CDKPJj_s.png",g=JSON.parse('{"title":"模型架构","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/llm.md","filePath":"fe/ai/llm.md"}'),m={name:"fe/ai/llm.md"};function d(p,a,f,c,h,_){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="模型架构" tabindex="-1">模型架构 <a class="header-anchor" href="#模型架构" aria-label="Permalink to &quot;模型架构&quot;">​</a></h1><h2 id="llm-大语言模型" tabindex="-1">LLM 大语言模型 <a class="header-anchor" href="#llm-大语言模型" aria-label="Permalink to &quot;LLM 大语言模型&quot;">​</a></h2><p>大型语言模型，英文全称 Large Language Model，简称 LLM。是指参数规模通常在数十亿到数万亿之间的深度神经网络，专门设计用于理解和生成人类语言。目前也是人工智能领域最热门的 AI，这些模型通过分析海量文本数据中的统计模式和语义关系，学会了语言的语法结构、语义内容和语用规则。LLM 的核心能力包括文本理解、内容生成、语言翻译、问答对话和代码编写等，代表了当前自然语言处理技术的最高水平。目前具有代表性的大模型包括 GPT-4，Claude-4，Gemini-2.5 等。</p><p><img src="'+s+'" alt="llm"></p><h2 id="transformer-架构" tabindex="-1">Transformer 架构 <a class="header-anchor" href="#transformer-架构" aria-label="Permalink to &quot;Transformer 架构&quot;">​</a></h2><p>Transformer 最早由谷歌于 2017 年在《Attention Is All You Need》论文提出，并且迅速成为自然语言处理（NLP）领域的标配，也是现今所有大模型的核心架构。其革命性的自注意力机制彻底改变了序列建模的方法。与传统的循环神经网络（RNN）不同，Transformer 能够并行处理序列中的所有位置，通过注意力权重矩阵捕获任意距离的依赖关系。这种架构设计不仅提高了训练效率，还显著增强了模型对长序列和复杂依赖关系的建模能力。</p><p><img src="'+l+'" alt="llm"></p><h2 id="混合专家模型-moe" tabindex="-1">混合专家模型（MoE） <a class="header-anchor" href="#混合专家模型-moe" aria-label="Permalink to &quot;混合专家模型（MoE）&quot;">​</a></h2><p>混合专家模型，是一种能够在保持计算效率的同时，大幅增加模型准确率的架构设计。混合专家模型包含多个专门化的子网络（专家）和门控网络，在处理任何用户输入时只激活其中一部分专家，也就是通过门控网络将任务分解后，激活部分特定专家完成任务。通过这种稀疏激活策略，既确保了任务的精准性，又提升了任务完成效率，MoE 模型能够拥有数万亿参数的理论容量，但实际计算成本仅相当于激活专家的总和，实现了参数规模与计算效率的平衡。</p><p><img src="'+n+'" alt="moe"></p><h2 id="扩散模型-diffusion-model" tabindex="-1">扩散模型（Diffusion Model） <a class="header-anchor" href="#扩散模型-diffusion-model" aria-label="Permalink to &quot;扩散模型（Diffusion Model）&quot;">​</a></h2><p>扩散模型是一类生成式 AI 模型，在图像和音视频领域广泛应用，通过模拟数据的噪声扩散过程来学习数据分布，简单说就是模型根据用户输入，将数据从无到有，从无序到有序的完成特定图像或音视频生成任务。训练阶段，模型学习如何将噪声逐步添加到原始数据中；生成阶段，模型从随机噪声开始，通过逆向扩散过程逐步去除噪声，最终生成高质量的数据样本。这种方法在图像生成、音频合成等领域取得了卓越的效果，生成内容的质量和多样性都达到了前所未有的水平。</p><p><img src="'+i+'" alt="moe"></p>',13)]))}const b=e(m,[["render",d]]);export{g as __pageData,b as default};
